    edit: { ...edit, modes: editModes },
    editConfirm: confirm,
    secondaryHelp,
    tankInfo,
    pause,
    tactical: {
      radar: geometry(116),
      enemyLife: geometry(1999),
      allyLife: geometry(2194),
    },
    fire: {
      ...fire,
      layouts: Array.from({ length: sprites.get(fire.symbol)!.frameCount }, (_, i) =>
        layout(fire.symbol, i + 1),
      ),
    },
    secondary: layout(1443),
    texts,
  }) + '\n',
);
